actions.command:
cat > main.go <<'EOF'
package main

import (
    "bufio"
    "encoding/json"
    "flag"
    "fmt"
    "io"
    "os"
    "path"
    "regexp"
    "sort"
    "strconv"
    "strings"
    "unicode/utf8"
)

const usageText = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

// Event is the public JSON shape emitted by `go test -json`.
type Event struct {
    Time    string  `json:"Time"`
    Action  string  `json:"Action"`
    Package string  `json:"Package"`
    Test    string  `json:"Test"`
    Elapsed float64 `json:"Elapsed"`
    Output  string  `json:"Output"`
}

type Options struct {
    all       bool
    pass      bool
    skip      bool
    notests   bool
    small     bool
    slow      int
    sortBy    string
    noColor   bool
    format    string
    file      string
    follow    bool
    followOut string
    inclTime  bool
    progress  bool
    compare   string
    trimPath  string
}

type TestRec struct {
    Name    string
    Package string
    Status  string
    Elapsed float64
    Order   int
    Outputs []string
}

type PackageRec struct {
    Name          string
    Order         int
    Status        string
    Elapsed       float64
    Cached        bool
    Cover         string
    CoverVal      float64
    HasCover      bool
    Pass, Fail    int
    Skip          int
    CountValid    bool
    NoTest        bool
    NoTestReason  string
    BuildFailed   bool
    BuildReason   string
    Panic         bool
    PanicTest     string
    PanicLines    []string
    panicStarted  bool
    Tests         map[string]*TestRec
    TestOrder     []*TestRec
    completionSeq int
}

type Parser struct {
    opts       Options
    packages   map[string]*PackageRec
    order      []*PackageRec
    parseable  int
    testSeq    int
    completeSeq int
    nonJSON    []string
    followW    io.Writer
}

func main() {
    os.Exit(run())
}

func run() int {
    opts, code, done := parseFlags(os.Args[1:])
    if done {
        return code
    }

    if opts.noColor || os.Getenv("NO_COLOR") != "" {
        opts.noColor = true
    }

    if opts.sortBy != "name" && opts.sortBy != "elapsed" && opts.sortBy != "cover" {
        fmt.Printf("invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", opts.sortBy)
        return 0
    }
    if opts.format != "basic" && opts.format != "plain" && opts.format != "markdown" {
        fmt.Printf("invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", opts.format)
        return 0
    }

    var in io.ReadCloser
    if opts.file != "" {
        f, err := os.Open(opts.file)
        if err != nil {
            fmt.Println(err)
            return 1
        }
        in = f
    } else {
        st, err := os.Stdin.Stat()
        if err != nil || (st.Mode()&os.ModeCharDevice) != 0 || st.Mode().IsRegular() {
            fmt.Println("stdin must be a pipe, or use -file to open a go test output file")
            return 1
        }
        in = os.Stdin
    }
    if in != os.Stdin {
        defer in.Close()
    }

    var followFile *os.File
    if opts.followOut != "" {
        f, err := os.Create(opts.followOut)
        if err != nil {
            fmt.Println(err)
            return 0
        }
        followFile = f
        defer followFile.Close()
    }

    if opts.compare != "" {
        f, err := os.Open(opts.compare)
        if err != nil {
            fmt.Printf("warning: failed to open against file: %s\n", opts.compare)
        } else {
            f.Close()
        }
    }

    p := &Parser{opts: opts, packages: map[string]*PackageRec{}}
    if followFile != nil {
        p.followW = followFile
    } else if opts.follow {
        p.followW = os.Stdout
    }
    p.parse(in)
    p.processNonJSON()
    p.finalize()

    if p.parseable == 0 {
        fmt.Println("no parsable events: Make sure to run go test with -json flag")
        return 1
    }

    r := Renderer{opts: opts, packages: p.order}
    r.Render()

    if p.hasBuildFailure() {
        return 2
    }
    if p.hasFailure() {
        return 1
    }
    return 0
}

func parseFlags(args []string) (Options, int, bool) {
    var opts Options
    opts.sortBy = "name"
    opts.format = "basic"

    fs := flag.NewFlagSet("tparse", flag.ContinueOnError)
    fs.SetOutput(os.Stdout)
    fs.Usage = func() { fmt.Print(usageText) }

    h := fs.Bool("h", false, "")
    help := fs.Bool("help", false, "")
    v := fs.Bool("v", false, "")
    version := fs.Bool("version", false, "")
    fs.BoolVar(&opts.all, "all", false, "")
    fs.BoolVar(&opts.pass, "pass", false, "")
    fs.BoolVar(&opts.skip, "skip", false, "")
    fs.BoolVar(&opts.notests, "notests", false, "")
    fs.BoolVar(&opts.small, "smallscreen", false, "")
    fs.IntVar(&opts.slow, "slow", 0, "")
    fs.StringVar(&opts.sortBy, "sort", "name", "")
    fs.BoolVar(&opts.noColor, "nocolor", false, "")
    fs.StringVar(&opts.format, "format", "basic", "")
    fs.StringVar(&opts.file, "file", "", "")
    fs.BoolVar(&opts.follow, "follow", false, "")
    fs.StringVar(&opts.followOut, "follow-output", "", "")
    fs.BoolVar(&opts.inclTime, "include-timestamp", false, "")
    fs.BoolVar(&opts.progress, "progress", false, "")
    fs.StringVar(&opts.compare, "compare", "", "")
    fs.StringVar(&opts.trimPath, "trimpath", "", "")

    err := fs.Parse(args)
    if err != nil {
        return opts, 2, true
    }
    if *h || *help {
        fmt.Print(usageText)
        return opts, 0, true
    }
    if *v || *version {
        fmt.Println("tparse version: (devel)")
        return opts, 0, true
    }
    return opts, 0, false
}

func (p *Parser) pkg(name string) *PackageRec {
    if pr, ok := p.packages[name]; ok {
        return pr
    }
    pr := &PackageRec{Name: name, Order: len(p.order), Status: "", CountValid: true, Tests: map[string]*TestRec{}}
    p.packages[name] = pr
    p.order = append(p.order, pr)
    return pr
}

func (pr *PackageRec) test(name string, seq *int) *TestRec {
    if tr, ok := pr.Tests[name]; ok {
        return tr
    }
    tr := &TestRec{Name: name, Package: pr.Name, Order: *seq}
    *seq++
    pr.Tests[name] = tr
    pr.TestOrder = append(pr.TestOrder, tr)
    return tr
}

func (p *Parser) parse(r io.Reader) {
    scanner := bufio.NewScanner(r)
    // go test output lines can be long; allow sizeable stack traces/log lines.
    scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
    for scanner.Scan() {
        line := scanner.Text()
        var ev Event
        if err := json.Unmarshal([]byte(line), &ev); err != nil {
            p.nonJSON = append(p.nonJSON, line)
            continue
        }
        p.parseable++
        p.handleEvent(ev)
    }
}

var covRe = regexp.MustCompile(`coverage:\s+([0-9]+(?:\.[0-9]+)?)%`)

func (p *Parser) handleEvent(ev Event) {
    pr := p.pkg(ev.Package)

    switch ev.Action {
    case "start":
        return
    case "run":
        if ev.Test != "" {
            pr.test(ev.Test, &p.testSeq)
        }
        return
    case "output":
        p.handleOutput(pr, ev)
        return
    case "pass", "fail", "skip":
        status := strings.ToUpper(ev.Action)
        if ev.Test != "" {
            tr := pr.test(ev.Test, &p.testSeq)
            if tr.Status == "" {
                switch status {
                case "PASS":
                    pr.Pass++
                case "FAIL":
                    pr.Fail++
                case "SKIP":
                    pr.Skip++
                }
            } else if tr.Status != status {
                decrementCount(pr, tr.Status)
                incrementCount(pr, status)
            }
            tr.Status = status
            tr.Elapsed = ev.Elapsed
        } else {
            pr.Status = status
            pr.Elapsed = ev.Elapsed
            p.completeSeq++
            pr.completionSeq = p.completeSeq
            if p.opts.progress {
                fmt.Printf("[%s]\t%9.2fs\t%s\n", colorStatus(status, !p.opts.noColor), ev.Elapsed, pr.Name)
            }
        }
    default:
        // A syntactically-valid but non go-test event is still considered parsable.
        // The original tool ends up showing a single odd package row; emulate that.
        if ev.Package == "" && ev.Action == "" && ev.Test == "" {
            pr.CountValid = true
            pr.Fail = 1
        }
    }
}

func incrementCount(pr *PackageRec, status string) {
    switch status {
    case "PASS": pr.Pass++
    case "FAIL": pr.Fail++
    case "SKIP": pr.Skip++
    }
}
func decrementCount(pr *PackageRec, status string) {
    switch status {
    case "PASS": if pr.Pass > 0 { pr.Pass-- }
    case "FAIL": if pr.Fail > 0 { pr.Fail-- }
    case "SKIP": if pr.Skip > 0 { pr.Skip-- }
    }
}

func (p *Parser) handleOutput(pr *PackageRec, ev Event) {
    out := ev.Output
    if p.followW != nil && shouldFollow(out) {
        if p.opts.inclTime {
            fmt.Fprint(p.followW, ev.Time+" "+out)
        } else {
            fmt.Fprint(p.followW, out)
        }
    }

    if ev.Test != "" {
        tr := pr.test(ev.Test, &p.testSeq)
        tr.Outputs = append(tr.Outputs, out)
        trimmed := strings.TrimSpace(out)
        if strings.HasPrefix(trimmed, "panic:") {
            pr.Panic = true
            pr.Status = "PANIC"
            pr.CountValid = false
            if pr.PanicTest == "" { pr.PanicTest = ev.Test }
            pr.panicStarted = true
        }
        if pr.panicStarted {
            // Omit the testing framework's preceding --- FAIL line; include panic text onward.
            if !strings.HasPrefix(strings.TrimSpace(out), "--- FAIL:") && !strings.HasPrefix(strings.TrimSpace(out), "=== RUN") {
                pr.PanicLines = append(pr.PanicLines, out)
            }
        }
        return
    }

    // Package-level output.
    if strings.Contains(out, "[no test files]") {
        pr.NoTest = true
        pr.NoTestReason = "[no test files]"
    }
    if strings.Contains(out, "[no tests to run]") || strings.Contains(out, "no tests to run") {
        pr.NoTest = true
        pr.NoTestReason = "[no tests to run]"
    }
    if strings.Contains(out, "(cached)") {
        pr.Cached = true
    }
    if m := covRe.FindStringSubmatch(out); m != nil {
        pr.Cover = m[1] + "%"
        if v, err := strconv.ParseFloat(m[1], 64); err == nil {
            pr.CoverVal = v
            pr.HasCover = true
        }
    }
    if pr.panicStarted {
        trim := strings.TrimSpace(out)
        if trim != "" && trim != "FAIL" && trim != "PASS" && !strings.HasPrefix(trim, "ok ") {
            pr.PanicLines = append(pr.PanicLines, out)
        }
    }
}

func shouldFollow(out string) bool {
    t := strings.TrimSpace(out)
    if t == "" { return false }
    if strings.HasPrefix(t, "=== RUN") { return false }
    if strings.HasPrefix(t, "--- PASS:") || strings.HasPrefix(t, "--- SKIP:") { return false }
    if t == "PASS" || t == "FAIL" { return false }
    if strings.HasPrefix(t, "ok ") || strings.HasPrefix(t, "? ") { return false }
    return true
}

var buildFailRe = regexp.MustCompile(`^FAIL\s+(\S+)\s+(\[[^\]]+\])`)

func (p *Parser) processNonJSON() {
    if p.parseable == 0 { return }
    for _, line := range p.nonJSON {
        m := buildFailRe.FindStringSubmatch(line)
        if m == nil { continue }
        pr := p.pkg(m[1])
        pr.Status = "FAIL"
        pr.Elapsed = 0
        pr.CountValid = false
        pr.BuildFailed = true
        pr.BuildReason = m[2]
    }
}

func (p *Parser) finalize() {
    for _, pr := range p.order {
        if pr.Panic {
            pr.Status = "PANIC"
            pr.CountValid = false
            pr.Pass, pr.Fail, pr.Skip = 0, 0, 0
            pr.Elapsed = 0
            continue
        }
        if pr.BuildFailed {
            pr.Status = "FAIL"
            pr.CountValid = false
            continue
        }
        if pr.Status == "" {
            if pr.Fail > 0 { pr.Status = "FAIL" } else if pr.Pass > 0 || pr.Skip > 0 { pr.Status = "PASS" }
        }
    }
}

func (p *Parser) hasFailure() bool {
    for _, pr := range p.order {
        if pr.BuildFailed || pr.Panic || pr.Status == "FAIL" || pr.Fail > 0 { return true }
    }
    return false
}
func (p *Parser) hasBuildFailure() bool {
    for _, pr := range p.order { if pr.BuildFailed { return true } }
    return false
}

// ---------------- Rendering ----------------

type Renderer struct {
    opts     Options
    packages []*PackageRec
}

func (r Renderer) Render() {
    if r.opts.format == "markdown" {
        r.renderMarkdown()
        return
    }

    showTests := r.opts.all || r.opts.pass || r.opts.skip
    if showTests {
        rows := r.testRows(false)
        if len(rows) > 0 {
            fmt.Print(renderTable(r.opts.format, []string{"Status", "Elapsed", "Test", "Package"}, rows, testAligns(), !r.opts.noColor, false))
        }
    }

    r.renderPanicAndFailures(false)

    rows := r.packageRows(false)
    fmt.Print(renderTable(r.opts.format, []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}, rows, pkgAligns(), !r.opts.noColor, false))
}

func (r Renderer) renderMarkdown() {
    showTests := r.opts.all || r.opts.pass || r.opts.skip
    if showTests {
        r.renderMarkdownTestSections()
    }
    r.renderPanicAndFailures(true)
    rows := r.packageRows(true)
    fmt.Print(renderTable("markdown", []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}, rows, pkgAligns(), !r.opts.noColor, true))
}

func (r Renderer) sortedPackages(includeNoTests bool) []*PackageRec {
    var build []*PackageRec
    var normal []*PackageRec
    var notests []*PackageRec
    for _, pr := range r.packages {
        if pr.BuildFailed {
            build = append(build, pr)
            continue
        }
        if pr.NoTest && pr.Pass+pr.Fail+pr.Skip == 0 && !pr.Panic {
            if includeNoTests { notests = append(notests, pr) }
            continue
        }
        normal = append(normal, pr)
    }
    sort.SliceStable(build, func(i,j int) bool { return build[i].Order < build[j].Order })
    sortPkgSlice(normal, r.opts.sortBy)
    sortPkgSlice(notests, r.opts.sortBy)
    out := append([]*PackageRec{}, build...)
    out = append(out, normal...)
    out = append(out, notests...)
    return out
}

func sortPkgSlice(pkgs []*PackageRec, by string) {
    sort.SliceStable(pkgs, func(i, j int) bool {
        a, b := pkgs[i], pkgs[j]
        switch by {
        case "elapsed":
            if a.Elapsed != b.Elapsed { return a.Elapsed > b.Elapsed }
        case "cover":
            if a.HasCover != b.HasCover { return a.HasCover }
            if a.CoverVal != b.CoverVal { return a.CoverVal > b.CoverVal }
        }
        if a.Name != b.Name { return a.Name < b.Name }
        return a.Order < b.Order
    })
}

func (r Renderer) displayPkg(name string) string {
    if r.opts.small {
        base := path.Base(name)
        if base != "." && base != "/" { return base }
    }
    if r.opts.trimPath != "" {
        return strings.TrimPrefix(name, r.opts.trimPath)
    }
    return name
}

func (r Renderer) displayTest(name string) string {
    if r.opts.small && strings.Count(name, "/") > 0 && displayWidth(name) > 30 {
        parts := strings.Split(name, "/")
        for i := 1; i < len(parts); i++ { parts[i] = " /" + parts[i] }
        return strings.Join(parts, "\n")
    }
    return name
}

func (r Renderer) testRows(markdown bool) [][]string {
    showPass := r.opts.all || r.opts.pass
    showSkip := r.opts.all || r.opts.skip
    pkgs := r.sortedPackages(false)
    var rows [][]string
    firstPkg := true
    for _, pr := range pkgs {
        if pr.Panic || pr.BuildFailed { continue }
        var pkgRows [][]string
        if showPass {
            passes := testsByStatus(pr, "PASS")
            sort.SliceStable(passes, func(i,j int) bool {
                if passes[i].Elapsed != passes[j].Elapsed { return passes[i].Elapsed > passes[j].Elapsed }
                return passes[i].Order < passes[j].Order
            })
            if r.opts.slow > 0 && len(passes) > r.opts.slow { passes = passes[:r.opts.slow] }
            for _, tr := range passes { pkgRows = append(pkgRows, r.testRow(tr, markdown)) }
        }
        if showSkip {
            for _, tr := range testsByStatus(pr, "SKIP") { pkgRows = append(pkgRows, r.testRow(tr, markdown)) }
        }
        // Failed test rows are displayed whenever a test table is requested.
        for _, tr := range testsByStatus(pr, "FAIL") { pkgRows = append(pkgRows, r.testRow(tr, markdown)) }
        if len(pkgRows) == 0 { continue }
        if !firstPkg { rows = append(rows, []string{"", "", "", ""}) }
        firstPkg = false
        rows = append(rows, pkgRows...)
    }
    return rows
}

func testsByStatus(pr *PackageRec, status string) []*TestRec {
    out := []*TestRec{}
    for _, tr := range pr.TestOrder {
        if tr.Status == status { out = append(out, tr) }
    }
    return out
}

func (r Renderer) testRow(tr *TestRec, markdown bool) []string {
    st := tr.Status
    if markdown && !r.opts.noColor { st = emojiStatus(st) }
    return []string{st, fmt.Sprintf("%.2f", tr.Elapsed), r.displayTest(tr.Name), r.displayPkg(tr.Package)}
}

func (r Renderer) packageRows(markdown bool) [][]string {
    pkgs := r.sortedPackages(r.opts.notests)
    rows := [][]string{}
    for _, pr := range pkgs {
        // Skip packages with no tests unless requested; build/panic were handled separately.
        if pr.NoTest && pr.Pass+pr.Fail+pr.Skip == 0 && !pr.BuildFailed && !pr.Panic && !r.opts.notests {
            continue
        }
        rows = append(rows, r.packageRow(pr, markdown))
    }
    return rows
}

func (r Renderer) packageRow(pr *PackageRec, markdown bool) []string {
    status := pr.Status
    elapsed := fmt.Sprintf("%.2fs", pr.Elapsed)
    pkg := r.displayPkg(pr.Name)
    cover := "--"
    pass, fail, skip := "--", "--", "--"

    if pr.NoTest && pr.Pass+pr.Fail+pr.Skip == 0 && !pr.BuildFailed && !pr.Panic {
        status = "NOTEST"
        if pr.NoTestReason != "" { pkg += "\n" + pr.NoTestReason }
    } else if pr.BuildFailed {
        status = "FAIL"
        if pr.BuildReason != "" { pkg += "\n" + pr.BuildReason }
    } else if pr.Panic {
        status = "PANIC"
    }

    if pr.Cached && !pr.Panic && !pr.BuildFailed && !(pr.NoTest && pr.Pass+pr.Fail+pr.Skip == 0) {
        elapsed = "(cached)"
    }
    if pr.HasCover { cover = pr.Cover }
    if pr.CountValid && !pr.BuildFailed && !pr.Panic && !(pr.NoTest && pr.Pass+pr.Fail+pr.Skip == 0) {
        pass, fail, skip = strconv.Itoa(pr.Pass), strconv.Itoa(pr.Fail), strconv.Itoa(pr.Skip)
    }
    if markdown && !r.opts.noColor { status = emojiStatus(status) }
    return []string{status, elapsed, pkg, cover, pass, fail, skip}
}

func (r Renderer) renderPanicAndFailures(markdown bool) {
    pkgs := r.sortedPackages(false)
    for _, pr := range pkgs {
        if pr.Panic { fmt.Print(r.panicSummary(pr, markdown)) }
    }
    for _, pr := range pkgs {
        if pr.BuildFailed || pr.Panic { continue }
        if pr.Status == "FAIL" || pr.Fail > 0 {
            detail := r.failureDetail(pr, markdown)
            if markdown {
                prefix := "FAIL"
                if !r.opts.noColor { prefix = "🔴 FAIL" }
                fmt.Printf("## %s • %s\n\n", prefix, pr.Name)
                fmt.Printf("```\n%s```\n\n", detail)
            } else {
                fmt.Print(failBox("FAIL", "package: "+pr.Name, !r.opts.noColor, 0))
                fmt.Println()
                fmt.Print(detail)
            }
        }
    }
}

func (r Renderer) panicSummary(pr *PackageRec, markdown bool) string {
    var b strings.Builder
    title := fmt.Sprintf("PANIC • %s", pr.Name)
    if pr.PanicTest != "" { title += " • " + pr.PanicTest }
    if markdown {
        if !r.opts.noColor { title = "🔴 " + title }
        b.WriteString(padRight("## "+title, 96))
        b.WriteByte('\n')
    } else {
        extra := "package: " + pr.Name
        if pr.PanicTest != "" { extra += " • " + pr.PanicTest }
        b.WriteString(failBox("PANIC", extra, !r.opts.noColor, 96))
    }
    for _, raw := range pr.PanicLines {
        line := strings.TrimRight(raw, "\r\n")
        line = strings.ReplaceAll(line, "\t", "    ")
        b.WriteString(padRight(line, 96))
        b.WriteByte('\n')
    }
    b.WriteString(padRight("", 96))
    b.WriteByte('\n')
    return b.String()
}

func (r Renderer) failureDetail(pr *PackageRec, markdown bool) string {
    groups := r.failureGroups(pr)
    if len(groups) == 0 { return "\n" }
    var b strings.Builder
    for gi, g := range groups {
        if gi > 0 {
            b.WriteString(strings.Repeat("─", 96))
            b.WriteByte('\n')
            b.WriteString(strings.Repeat(" ", 96))
            b.WriteByte('\n')
        }
        for _, h := range g.headers {
            if !markdown && !r.opts.noColor {
                b.WriteString("\x1b[31m" + h + "\x1b[0m\n")
            } else {
                b.WriteString(h + "\n")
            }
        }
        if len(g.body) > 0 {
            b.WriteByte('\n')
            for _, line := range g.body { b.WriteString(line + "\n") }
            b.WriteByte('\n')
        }
    }
    return b.String()
}

type failGroup struct { root string; headers []string; body []string; order int }

func (r Renderer) failureGroups(pr *PackageRec) []failGroup {
    groupMap := map[string]*failGroup{}
    order := []string{}
    for _, tr := range pr.TestOrder {
        if tr.Status != "FAIL" { continue }
        root := tr.Name
        if idx := strings.Index(root, "/"); idx >= 0 { root = root[:idx] }
        if _, ok := groupMap[root]; !ok {
            groupMap[root] = &failGroup{root: root, order: tr.Order}
            order = append(order, root)
        }
    }
    sort.SliceStable(order, func(i,j int) bool { return groupMap[order[i]].order < groupMap[order[j]].order })
    for _, root := range order {
        g := groupMap[root]
        // Parent header first, then failing children.
        if tr := pr.Tests[root]; tr != nil && tr.Status == "FAIL" {
            g.headers = append(g.headers, failHeaders(tr.Outputs)...)
        }
        for _, tr := range pr.TestOrder {
            if tr.Status != "FAIL" || tr.Name == root || !strings.HasPrefix(tr.Name, root+"/") { continue }
            g.headers = append(g.headers, failHeaders(tr.Outputs)...)
        }
        // Body in event order, all failing tests in group.
        for _, tr := range pr.TestOrder {
            if tr.Status != "FAIL" { continue }
            if tr.Name != root && !strings.HasPrefix(tr.Name, root+"/") { continue }
            g.body = append(g.body, failBody(tr.Outputs)...)
        }
    }
    out := []failGroup{}
    for _, root := range order {
        g := groupMap[root]
        if len(g.headers) == 0 && len(g.body) == 0 { continue }
        out = append(out, *g)
    }
    return out
}

func failHeaders(outputs []string) []string {
    hs := []string{}
    for _, out := range outputs {
        line := strings.TrimRight(out, "\r\n")
        if strings.HasPrefix(strings.TrimSpace(line), "--- FAIL:") { hs = append(hs, line) }
    }
    return hs
}

func failBody(outputs []string) []string {
    out := []string{}
    for _, raw := range outputs {
        line := strings.TrimRight(raw, "\r\n")
        t := strings.TrimSpace(line)
        if t == "" { out = append(out, line); continue }
        if strings.HasPrefix(t, "=== RUN") || strings.HasPrefix(t, "--- FAIL:") || strings.HasPrefix(t, "--- PASS:") || strings.HasPrefix(t, "--- SKIP:") { continue }
        if strings.HasPrefix(t, "panic:") { continue }
        out = append(out, line)
    }
    // Trim leading/trailing empty lines in ordinary failure bodies.
    for len(out) > 0 && strings.TrimSpace(out[0]) == "" { out = out[1:] }
    for len(out) > 0 && strings.TrimSpace(out[len(out)-1]) == "" { out = out[:len(out)-1] }
    return out
}

func failBox(status, extra string, color bool, padTo int) string {
    rawText := fmt.Sprintf("   %s  %s   ", status, extra)
    inner := displayWidth(rawText)
    top := "┏" + strings.Repeat("━", inner) + "┓"
    bot := "┗" + strings.Repeat("━", inner) + "┛"
    statusText := status
    if color { statusText = colorStatus(colorStatus(status, true), true) }
    mid := "┃   " + statusText + "  " + extra + "   ┃"
    if color {
        top = "\x1b[38;5;103m" + top + "\x1b[0m"
        bot = "\x1b[38;5;103m" + bot + "\x1b[0m"
        mid = "\x1b[38;5;103m┃\x1b[0m   " + statusText + "  " + extra + "   \x1b[38;5;103m┃\x1b[0m"
    }
    if padTo > 0 {
        top = padRight(top, padTo)
        mid = padRight(mid, padTo)
        bot = padRight(bot, padTo)
    }
    return top + "\n" + mid + "\n" + bot + "\n"
}

// ---------------- Table rendering ----------------

type align int
const (
    alignLeft align = iota
    alignCenter
)

func testAligns() []align { return []align{alignCenter, alignCenter, alignLeft, alignLeft} }
func pkgAligns() []align { return []align{alignCenter, alignCenter, alignLeft, alignCenter, alignCenter, alignCenter, alignCenter} }

func renderTable(format string, headers []string, rows [][]string, aligns []align, color bool, markdown bool) string {
    switch format {
    case "plain": return renderPlain(headers, rows, aligns, color)
    case "markdown": return renderMarkdownTable(headers, rows, aligns, color)
    default: return renderBasic(headers, rows, aligns, color)
    }
}

func colorizeCell(colHeader, val string, color bool) string {
    if !color { return val }
    // Do not color multiline blank continuations or emoji markdown values.
    plain := stripANSI(val)
    switch colHeader {
    case "Status":
        return colorStatus(val, true)
    case "Cover":
        if strings.HasSuffix(plain, "%") {
            n, err := strconv.ParseFloat(strings.TrimSuffix(strings.TrimSpace(plain), "%"), 64)
            if err == nil && n > 0 {
                if n >= 80 { return "\x1b[92m" + val + "\x1b[0m" }
                if n > 50 || n >= 50 { // keep gofmt from simplifying the threshold comment
                    if n < 80 { return "\x1b[93m" + val + "\x1b[0m" }
                }
                return "\x1b[91m" + val + "\x1b[0m"
            }
        }
    }
    return val
}

func colorStatus(s string, color bool) string {
    if !color { return s }
    bare := stripANSI(s)
    switch bare {
    case "PASS": return "\x1b[92m" + s + "\x1b[0m"
    case "FAIL", "PANIC": return "\x1b[91m" + s + "\x1b[0m"
    case "SKIP", "NOTEST": return "\x1b[93m" + s + "\x1b[0m"
    default: return s
    }
}

func emojiStatus(s string) string {
    switch s {
    case "PASS": return "🟢 PASS"
    case "FAIL": return "🔴 FAIL"
    case "SKIP": return "🟡 SKIP"
    case "PANIC": return "🔴 PANIC"
    case "NOTEST": return "🟡 NOTEST"
    default: return s
    }
}

func computeWidths(headers []string, rows [][]string) []int {
    widths := make([]int, len(headers))
    for i,h := range headers { widths[i] = displayWidth(h) }
    for _, row := range rows {
        for i := range headers {
            val := ""
            if i < len(row) { val = row[i] }
            for _, line := range strings.Split(val, "\n") {
                if w := displayWidth(line); w > widths[i] { widths[i] = w }
            }
        }
    }
    return widths
}

func renderBasic(headers []string, rows [][]string, aligns []align, color bool) string {
    widths := computeWidths(headers, rows)
    var b strings.Builder
    b.WriteString(borderLine("╭", "┬", "╮", "─", widths)); b.WriteByte('\n')
    b.WriteString(renderBasicLine(headers, widths, centerAligns(len(headers)), nil, false)); b.WriteByte('\n')
    b.WriteString(borderLine("├", "┼", "┤", "─", widths)); b.WriteByte('\n')
    for _, row := range rows {
        split := splitRow(row, len(headers))
        height := 1
        for _, lines := range split { if len(lines) > height { height = len(lines) } }
        for h := 0; h < height; h++ {
            vals := make([]string, len(headers))
            for c := range headers {
                if h < len(split[c]) { vals[c] = split[c][h] }
            }
            b.WriteString(renderBasicLine(vals, widths, aligns, headers, color)); b.WriteByte('\n')
        }
    }
    b.WriteString(borderLine("╰", "┴", "╯", "─", widths)); b.WriteByte('\n')
    return b.String()
}

func centerAligns(n int) []align { a:=make([]align,n); for i:=range a { a[i]=alignCenter }; return a }

func borderLine(left, mid, right, fill string, widths []int) string {
    parts := make([]string, len(widths))
    for i,w := range widths { parts[i] = strings.Repeat(fill, w+2) }
    return left + strings.Join(parts, mid) + right
}

func splitRow(row []string, n int) [][]string {
    out := make([][]string, n)
    for i:=0;i<n;i++ {
        val := ""
        if i < len(row) { val = row[i] }
        out[i] = strings.Split(val, "\n")
    }
    return out
}

func renderBasicLine(vals []string, widths []int, aligns []align, headers []string, color bool) string {
    cells := make([]string, len(widths))
    for i,w := range widths {
        v := vals[i]
        if headers != nil { v = colorizeCell(headers[i], v, color) }
        cells[i] = " " + alignText(v, w, aligns[i]) + " "
    }
    return "│" + strings.Join(cells, "│") + "│"
}

func renderPlain(headers []string, rows [][]string, aligns []align, color bool) string {
    widths := computeWidths(headers, rows)
    var b strings.Builder
    b.WriteString(renderPlainLine(headers, widths, centerAligns(len(headers)), nil, false)); b.WriteByte('\n')
    b.WriteString(strings.Repeat(" ", plainLineWidth(widths))); b.WriteByte('\n')
    for _, row := range rows {
        split := splitRow(row, len(headers))
        height := 1
        for _, lines := range split { if len(lines)>height { height=len(lines) } }
        for h:=0; h<height; h++ {
            vals := make([]string, len(headers))
            for c:=range headers { if h<len(split[c]) { vals[c]=split[c][h] } }
            b.WriteString(renderPlainLine(vals, widths, aligns, headers, color)); b.WriteByte('\n')
        }
    }
    return b.String()
}

func plainLineWidth(widths []int) int {
    total := 0
    for _, w := range widths { total += w + 2 }
    if len(widths) > 1 { total += len(widths)-1 }
    return total
}

func renderPlainLine(vals []string, widths []int, aligns []align, headers []string, color bool) string {
    cells := make([]string, len(widths))
    for i,w := range widths {
        v := vals[i]
        if headers != nil { v = colorizeCell(headers[i], v, color) }
        cells[i] = " " + alignText(v, w, aligns[i]) + " "
    }
    return strings.Join(cells, " ")
}

func renderMarkdownTable(headers []string, rows [][]string, aligns []align, color bool) string {
    // In markdown, color=true means use emoji statuses only; ANSI is never emitted.
    widths := computeWidths(headers, rows)
    var b strings.Builder
    b.WriteString(renderMarkdownLine(headers, widths, centerAligns(len(headers)), nil)); b.WriteByte('\n')
    sep := make([]string, len(widths))
    for i,w := range widths { sep[i] = strings.Repeat("-", w+2) }
    b.WriteString("|" + strings.Join(sep, "|") + "|\n")
    for _, row := range rows {
        split := splitRow(row, len(headers))
        height := 1
        for _, lines := range split { if len(lines)>height { height=len(lines) } }
        for h:=0; h<height; h++ {
            vals := make([]string, len(headers))
            for c:=range headers { if h<len(split[c]) { vals[c]=split[c][h] } }
            b.WriteString(renderMarkdownLine(vals, widths, aligns, headers)); b.WriteByte('\n')
        }
    }
    return b.String()
}

func renderMarkdownLine(vals []string, widths []int, aligns []align, headers []string) string {
    cells := make([]string, len(widths))
    for i,w := range widths {
        v := vals[i]
        cells[i] = " " + alignText(v, w, aligns[i]) + " "
    }
    return "|" + strings.Join(cells, "|") + "|"
}

func (r Renderer) renderMarkdownTestSections() {
    pkgs := r.sortedPackages(false)
    for _, pr := range pkgs {
        if pr.Panic || pr.BuildFailed { continue }
        rowsWithPkg := r.testRowsForPackage(pr, true)
        if len(rowsWithPkg) == 0 { continue }
        fmt.Printf("## 📦 Package **`%s`**\n\n", r.displayPkg(pr.Name))
        fmt.Printf("Tests: ✓ %d passed | %d skipped | %d failed\n\n", pr.Pass, pr.Skip, pr.Fail)
        fmt.Println("<details>")
        fmt.Println()
        fmt.Println("<summary>Click for test summary</summary>")
        fmt.Println()
        rows := [][]string{}
        for _, rw := range rowsWithPkg { rows = append(rows, []string{rw[0], rw[1], rw[2]}) }
        fmt.Print(renderTable("markdown", []string{"Status", "Elapsed", "Test"}, rows, []align{alignCenter, alignCenter, alignLeft}, false, true))
        fmt.Println("</details>")
        fmt.Println()
        fmt.Println()
    }
}

func (r Renderer) testRowsForPackage(pr *PackageRec, markdown bool) [][]string {
    showPass := r.opts.all || r.opts.pass
    showSkip := r.opts.all || r.opts.skip
    rows := [][]string{}
    if showPass {
        passes := testsByStatus(pr, "PASS")
        sort.SliceStable(passes, func(i,j int) bool {
            if passes[i].Elapsed != passes[j].Elapsed { return passes[i].Elapsed > passes[j].Elapsed }
            return passes[i].Order < passes[j].Order
        })
        if r.opts.slow > 0 && len(passes) > r.opts.slow { passes = passes[:r.opts.slow] }
        for _, tr := range passes { rows = append(rows, r.testRow(tr, markdown)) }
    }
    if showSkip { for _, tr := range testsByStatus(pr, "SKIP") { rows = append(rows, r.testRow(tr, markdown)) } }
    for _, tr := range testsByStatus(pr, "FAIL") { rows = append(rows, r.testRow(tr, markdown)) }
    return rows
}

func alignText(s string, width int, a align) string {
    w := displayWidth(s)
    if w >= width { return s }
    pad := width - w
    if a == alignCenter {
        left := pad / 2
        right := pad - left
        return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
    }
    return s + strings.Repeat(" ", pad)
}

func padRight(s string, width int) string {
    w := displayWidth(s)
    if w >= width { return s }
    return s + strings.Repeat(" ", width-w)
}

func stripANSI(s string) string {
    var b strings.Builder
    inEsc := false
    for i := 0; i < len(s); i++ {
        c := s[i]
        if inEsc {
            if c == 'm' { inEsc = false }
            continue
        }
        if c == 0x1b {
            inEsc = true
            continue
        }
        b.WriteByte(c)
    }
    return b.String()
}

func displayWidth(s string) int {
    s = stripANSI(s)
    w := 0
    for len(s) > 0 {
        r, size := utf8.DecodeRuneInString(s)
        if r == utf8.RuneError && size == 1 { s = s[1:]; w++; continue }
        s = s[size:]
        if r == '\t' { w += 4; continue }
        if r >= 0x1F000 || (r >= 0x2600 && r <= 0x27BF) { w += 2 } else { w++ }
    }
    return w
}
